    if(entry.kind==='text'){if(!node.querySelector('.canvas-inline-text')){const content=[...node.childNodes].filter(n=>n.nodeType===3).map(n=>n.textContent).join('');if(content!==entry.value.content){for(const n of [...node.childNodes])if(n.nodeType===3)n.remove();node.prepend(document.createTextNode(entry.value.content));}}}
